let seedPromise: Promise<void> | null = null

export function ensureSeeded() {
  if (!seedPromise) {
    seedPromise = seedHub().catch((err) => {
      seedPromise = null
      throw err
    })
  }
  return seedPromise
}

function withSeedFile(r: Recurso): Recurso {
  const spec = SEED_PUBLIC_FILES.find((s) => s.id === r.id)
  if (!spec) return r
  const copied = copySeedPublicFile(spec)
  return {
    ...r,
    ruta: undefined,
    storageKey: copied.storageKey,
    mime: spec.mime,
    nombreOriginal: spec.nombreOriginal,
    size: copied.size,
  }
}

async function convertExistingSeedFiles() {
  const db = getDb()
  const rows = await db
    .select({
      id: recursos.id,
      ruta: recursos.ruta,
      storageKey: recursos.storageKey,
    })
    .from(recursos)
  for (const row of rows) {
    if (!shouldReplaceWithSeedFile(row)) continue
    const spec = SEED_PUBLIC_FILES.find((s) => s.id === row.id)
    if (!spec) continue
    const copied = copySeedPublicFile(spec)
    await db
      .update(recursos)
      .set({
        ruta: null,
        storageKey: copied.storageKey,
        mime: spec.mime,
        nombreOriginal: spec.nombreOriginal,
        size: copied.size,
      })
      .where(eq(recursos.id, row.id))
  }
}

// `infra_movimiento.idempotency_key` no existía en el batch de esquema
// (batch 1): parteActualizacionInputSchema exige `idempotencyKey` pero la
// tabla no tenía dónde guardarla. Mismo motivo que cualquier columna
// agregada con ALTER a una base poblada: ALTER TABLE ADD COLUMN no es
// idempotente y SQLite no permite agregar una columna NOT NULL a una tabla
// con filas, así que queda nullable. El índice único de HUB_DDL ya cubre las
// bases nuevas; acá sólo hace falta la columna para las que ya tenían la
// tabla creada sin ella.
export async function ensureMovimientoIdempotencyKeyColumn(): Promise<void> {
  const db = getDb()
  const info = await db.$client.execute("PRAGMA table_info('infra_movimiento')")
  const tieneColumna = info.rows.some((r) => String(r.name) === 'idempotency_key')
  if (!tieneColumna) {
    await db.$client.execute('ALTER TABLE infra_movimiento ADD COLUMN idempotency_key text')
  }
  await db.$client.execute(
    'CREATE UNIQUE INDEX IF NOT EXISTS `infra_movimiento_idempotency_key_uidx` ON `infra_movimiento` (`idempotency_key`)',
  )
}

// `infra_movimiento.episodio_id` llega con el batch E1 (episodios): enlaza el
// movimiento con el episodio que lo originó. Mismo motivo que idempotencyKey
// para quedar nullable y agregarse por ALTER: SQLite no permite agregar una
// columna NOT NULL a una tabla con filas. Sin asignación retroactiva: los
// movimientos históricos quedan en NULL. HUB_DDL ya cubre las bases nuevas;
// acá sólo hace falta la columna para las que ya tenían la tabla sin ella.
export async function ensureMovimientoEpisodioIdColumn(): Promise<void> {
  const db = getDb()
  const info = await db.$client.execute("PRAGMA table_info('infra_movimiento')")
  const tieneColumna = info.rows.some((r) => String(r.name) === 'episodio_id')
  if (!tieneColumna) {
    await db.$client.execute('ALTER TABLE infra_movimiento ADD COLUMN episodio_id text')
  }
}

// infra_acceso_nominal_log.problematica_id nace apuntando al modelo
// deprecado, retirado en la Fase 4; F3.3 la repuntó a infra_afectacion.id. Es texto plano
// SIN foreign key, así que el rename es barato — no hay índices ni
// constraints que reconstruir.
export async function ensureAccesoNominalLogAfectacionIdColumn(): Promise<void> {
  const db = getDb()
  const info = await db.$client.execute("PRAGMA table_info('infra_acceso_nominal_log')")
  const columnas = new Set(info.rows.map((r) => String(r.name)))
  if (columnas.has('afectacion_id')) return
  if (!columnas.has('problematica_id')) return // tabla creada ya con el nombre nuevo (DDL fresco)
  await db.$client.execute('ALTER TABLE infra_acceso_nominal_log RENAME COLUMN problematica_id TO afectacion_id')
}

// Id fijo y estable del único período que existe en esta etapa (protocolo
// ENOS 2026/2027, ver CONTRACT.md del batch de esquema: "la situación
// hidrometeorológica es UN período provincial, no un episodio por
// establecimiento"). No hay ABM de períodos todavía, así que sembrarlo con un
// id conocido evita tener que buscarlo por nombre.
export const PERIODO_ENOS_2026_2027_ID = 'periodo-enos-2026-2027'

// Siembra idempotente (onConflictDoNothing por id) del único período que
// existe en esta etapa (protocolo ENOS 2026/2027). El backfill que enlazaba
// problemáticas del modelo deprecado con partes se retiró en la Fase 4
// (modelo eliminado, datos de prueba sin backfill); el período se conserva
// porque pertenece al modelo de parte vivo: parte-consulta, el mapa y los
// tests lo esperan sembrado por ensureSeeded().
export async function sembrarPeriodoEnos(): Promise<void> {
  const db = getDb()
  await db
    .insert(infraPeriodo)
    .values({
      id: PERIODO_ENOS_2026_2027_ID,
      nombre: 'Protocolo ENOS 2026/2027',
      inicioEn: '2026-01-01T00:00:00.000Z',
      finEn: null,
      estado: 'vigente',
      creadaEn: new Date().toISOString(),
    })
    .onConflictDoNothing()
}

async function seedHub() {
  const db = getDb()
  await db.$client.executeMultiple(HUB_DDL)
  // F4.6: las tres tablas del modelo deprecado ya no se crean en HUB_DDL; se
  // dropean acá, donde antes vivían sus helpers ensure/backfill, para que una
  // base existente se limpie sola al arrancar. Los datos eran de prueba: sin
  // backfill, dropeo directo. IF EXISTS lo hace idempotente y el orden
  // hijos→padre evita violar las FK que apuntaban a la tabla madre.
  await db.$client.execute('DROP TABLE IF EXISTS `infra_problematica_alumno`')
  await db.$client.execute('DROP TABLE IF EXISTS `infra_problematica_seccion`')
  await db.$client.execute('DROP TABLE IF EXISTS `infra_problematica`')
  await ensureMovimientoIdempotencyKeyColumn()
  await ensureMovimientoEpisodioIdColumn()
  await ensureAccesoNominalLogAfectacionIdColumn()

  const [row] = await db.select({ n: count() }).from(niveles)
  if ((row?.n ?? 0) === 0) {
    const seeded = seedRecursos.map(withSeedFile)
    const tagJoins = seeded.flatMap((r) =>
      r.tagIds.map((tagId) => ({ recursoId: r.id, tagId })),
    )

    await db.transaction(async (tx) => {
      await tx.insert(niveles).values(seedNiveles)
      await tx.insert(tipos).values(seedTipos)
      await tx.insert(categorias).values(seedCategorias)
      await tx.insert(tags).values(seedTags)
      await tx.insert(recursos).values(
        seeded.map(
          ({ tagIds: _tagIds, audienciaNivelIds: _n, audienciaUserIds: _u, ...row }) =>
            row,
        ),
      )
      if (tagJoins.length > 0) {
        await tx.insert(recursoTags).values(tagJoins)
      }
    })
  } else {
    await convertExistingSeedFiles()
  }

  // Fuera del if: corre siempre, también sobre una base ya poblada, y nunca
  // toca la audiencia configurada del recurso (ver recurso-seed.ts).
  await upsertRecursoInfraestructura()

  // Motivos de infraestructura: siembra idempotente (onConflictDoNothing,
  // ver sembrarMotivos). Corre siempre, no sólo en la siembra inicial, para
  // cubrir instalaciones ya pobladas que suman esta migración. (El backfill
  // de categoria sobre el modelo deprecado se retiró en la Fase 4.)
  await sembrarMotivos()
  // Debe correr después de sembrar: renombra los comodines heredados y recién
  // ahí crea el índice único sobre `nombre`, que es lo que hace que
  // resolverCategoria pueda deducir la categoría sin ambigüedad.
  await ensureMotivoNombreUnico()

  // Modelo de parte (ver docs/especificacion-funcional-trayectoria-evento-hidrometeorologico.md):
  // siembra el período provincial. Idempotente, corre siempre.
  await sembrarPeriodoEnos()

  // Siembra ge_localizacion desde el JSON versionado si esta vacia: ge.sqlite
  // vive en el volumen y una instalacion nueva arrancaria sin escuelas.
  await ensureLocalizacionesSeeded()

  await seedFirstAdmin()
}

async function seedFirstAdmin() {
  const db = getDb()
  const [row] = await db.select({ n: count() }).from(user)
  if ((row?.n ?? 0) > 0) return

  const email = process.env.ADMIN_EMAIL
  const password = process.env.ADMIN_PASSWORD
  if (!email || !password) {
    console.warn(
      'Skipping first admin seed: ADMIN_EMAIL and ADMIN_PASSWORD are required',
    )
    return
  }

  const { auth } = await import('@/lib/auth')
  const ctx = await auth.$context
  const created = await ctx.internalAdapter.createUser(
    {
      email,
      name: 'Admin',
      role: 'admin',
      emailVerified: true,
    },
    { method: 'admin' },
  )
  await ctx.internalAdapter.createAccount({
    userId: created.id,
    accountId: created.id,
    providerId: 'credential',
    issuer: 'local:credential',
    password: await ctx.password.hash(password),
  })
}

// Máquina de estados de las verificaciones del batch E1 del protocolo ENOS.
// Una verificación es un pedido de confirmación a un establecimiento: nace
// 'pendiente' con una credencial de un solo uso (enlace público) y termina
// 'respondida' o 'cancelada'. Ver lib/db/schema.ts (infraVerificacion /
// infraVerificacionEvento) para el modelo y verificacion-token.ts para la
// credencial.
//
// Regla transversal: TODA transición de estado usa un UPDATE condicionado con
// `.returning()` (mismo patrón que lib/infraestructura/riesgo/job-run.ts).
// Nunca un select-then-act separado: entre el read y el write otra request
// concurrente puede cancelar o responder, y el WHERE es lo único que garantiza
// que gane una sola. El select posterior al UPDATE fallido sirve para
// *clasificar* el conflicto (404/409), no para decidir la escritura.
import { randomUUID } from 'node:crypto'
import { and, desc, eq, isNull, sql } from 'drizzle-orm'
import { getDb } from '@/lib/db'
import {
  infraAfectacion,
  infraMovimiento,
  infraParte,
  infraVerificacion,
  infraVerificacionEvento,
} from '@/lib/db/schema'
import { obtenerEpisodio } from '@/lib/infraestructura/episodios'
import {
  calcularVencimientoToken,
  generarToken,
  hashearToken,
  tokenExpirado,
} from './verificacion-token'

export type VerificacionRow = typeof infraVerificacion.$inferSelect

export type ResultadoTransicion =
  | { ok: true; verificacion: VerificacionRow; replay?: boolean }
  | { ok: false; status: 403 | 404 | 409 | 410; motivo: string }

type ResultadoRespuesta = 'sin_afectacion' | 'con_afectacion' | 'no_disponible'
type CanalRespuesta = 'enlace' | 'telefono' | 'whatsapp' | 'presencial' | 'otro'
type CanalAsistido = 'telefono' | 'whatsapp' | 'presencial' | 'otro'

type OrigenRespuesta =
  | { tipo: 'enlace'; token: string }
  | { tipo: 'asistida'; actorUserId: string; canal: CanalAsistido }

type CrearVerificacionInput = {
  episodioId: string
  cueAnexo: string
  solicitadaPorUserId: string
  vencimientoEn?: string | null
}

type CancelarVerificacionInput = {
  verificacionId: string
  actorUserId: string
  motivo?: string | null
}

type ResponderPorEnlaceInput = {
  verificacionId: string
  token: string
  resultado: ResultadoRespuesta
  movimientoId?: string | null
}

type ResponderAsistidaInput = {
  verificacionId: string
  actorUserId: string
  canal: CanalAsistido
  resultado: ResultadoRespuesta
  movimientoId?: string | null
}

// Emite un pedido de verificación. El `token` en claro viaja en la respuesta
// SÓLO acá: es el único momento en que existe fuera del proceso. La base
// guarda nada más que su sha256 (`tokenHash`), así que después de esta llamada
// no hay forma de recuperarlo — quien lo perdió tiene que pedir otro pedido.
//
// No reemplaza verificaciones anteriores del mismo CUE: una nueva solicitud
// convive con las previas (spec E1). Si el episodio no está abierto no se
// emiten pedidos.
export async function crearVerificacion(
  input: CrearVerificacionInput,
  ahora: Date = new Date(),
): Promise<
  | { ok: true; verificacion: VerificacionRow; token: string }
  | { ok: false; status: 404 | 409; motivo: 'episodio_no_existe' | 'episodio_cerrado' }
> {
  const db = getDb()
  const episodio = await obtenerEpisodio(input.episodioId)
  if (!episodio) return { ok: false, status: 404, motivo: 'episodio_no_existe' }
  if (episodio.estado !== 'abierto') return { ok: false, status: 409, motivo: 'episodio_cerrado' }

  const { token, tokenHash } = generarToken()
  const ahoraIso = ahora.toISOString()

  const [verificacion] = await db
    .insert(infraVerificacion)
    .values({
      id: randomUUID(),
      episodioId: input.episodioId,
      cueAnexo: input.cueAnexo,
      estado: 'pendiente',
      solicitadaEn: ahoraIso,
      solicitadaPorUserId: input.solicitadaPorUserId,
      vencimientoEn: input.vencimientoEn ?? null,
      resultado: null,
      discrepancia: 0,
      respondidaEn: null,
      respondidaCanal: null,
      respondidaPorUserId: null,
      movimientoId: null,
      canceladaEn: null,
      canceladaPorUserId: null,
      motivoCancelacion: null,
      tokenHash,
      // Vencimiento de la credencial (bloquea, 410), no el SLA informativo.
      tokenExpiraEn: calcularVencimientoToken(ahora),
      tokenRevocadoEn: null,
      tokenConsumidoEn: null,
      creadaEn: ahoraIso,
      actualizadaEn: ahoraIso,
    })
    .returning()

  await db.insert(infraVerificacionEvento).values({
    id: randomUUID(),
    verificacionId: verificacion.id,
    tipo: 'creada',
    actorTipo: 'usuario',
    actorUserId: input.solicitadaPorUserId,
    canal: null,
    motivo: null,
    correlacionId: null,
    creadaEn: ahoraIso,
  })

  return { ok: true, verificacion, token }
}

// Cancela un pedido pendiente. El UPDATE condicionado a estado='pendiente' es
// el árbitro de la carrera cancelar/responder: gana quien logre el UPDATE
// primero. El perdedor cae en el select de clasificación y recibe el estado
// real ya persistido, no una suposición.
export async function cancelarVerificacion(
  input: CancelarVerificacionInput,
  ahora: Date = new Date(),
): Promise<ResultadoTransicion> {
  const db = getDb()
  const ahoraIso = ahora.toISOString()

  const [actualizada] = await db
    .update(infraVerificacion)
    .set({
      estado: 'cancelada',
      canceladaEn: ahoraIso,
      canceladaPorUserId: input.actorUserId,
      motivoCancelacion: input.motivo ?? null,
      actualizadaEn: ahoraIso,
    })
    .where(
      and(
        eq(infraVerificacion.id, input.verificacionId),
        eq(infraVerificacion.estado, 'pendiente'),
      ),
    )
    .returning()

  if (actualizada) {
    await db.insert(infraVerificacionEvento).values({
      id: randomUUID(),
      verificacionId: input.verificacionId,
      tipo: 'cancelada',
      actorTipo: 'usuario',
      actorUserId: input.actorUserId,
      canal: null,
      motivo: input.motivo ?? null,
      correlacionId: null,
      creadaEn: ahoraIso,
    })
    return { ok: true, verificacion: actualizada }
  }

  // El UPDATE no matcheó: la fila no existe, ya estaba cancelada o ya se
  // respondió. El select sólo clasifica el motivo.
  const [fila] = await db
    .select()
    .from(infraVerificacion)
    .where(eq(infraVerificacion.id, input.verificacionId))
  if (!fila) return { ok: false, status: 404, motivo: 'no_existe' }
  if (fila.estado === 'cancelada') return { ok: false, status: 409, motivo: 'ya_cancelada' }
  if (fila.estado === 'respondida') return { ok: false, status: 409, motivo: 'ya_respondida' }
  return { ok: false, status: 409, motivo: fila.estado }
}

// true si existe al menos una afectación vigente (retirada_en IS NULL) para
// ese establecimiento dentro del período. Es la señal que convierte una
// respuesta 'sin_afectacion' en discrepancia: el director dice que no pasa
// nada mientras el parte registra lo contrario.
async function existeAfectacionVigente(cueAnexo: string, periodoId: string): Promise<boolean> {
  const db = getDb()
  const [fila] = await db
    .select({ uno: sql<number>`1` })
    .from(infraAfectacion)
    .innerJoin(infraParte, eq(infraAfectacion.parteId, infraParte.id))
    .where(
      and(
        eq(infraParte.cueAnexo, cueAnexo),
        eq(infraParte.periodoId, periodoId),
        isNull(infraAfectacion.retiradaEn),
      ),
    )
    .limit(1)
  return Boolean(fila)
}

// Defensa contra vínculo cruzado entre escuelas: un movimientoId sólo es
// válido para ESTA verificación si el parte al que pertenece es del mismo
// cueAnexo. Sin este chequeo, cualquier movimientoId ajeno (de otro CUE)
// quedaría enlazado igual — un bug real encontrado por revisión adversarial.
async function movimientoPerteneceAlCue(movimientoId: string, cueAnexo: string): Promise<boolean> {
  const db = getDb()
  const [fila] = await db
    .select({ cueAnexo: infraParte.cueAnexo })
    .from(infraMovimiento)
    .innerJoin(infraParte, eq(infraMovimiento.parteId, infraParte.id))
    .where(eq(infraMovimiento.id, movimientoId))
    .limit(1)
  return fila?.cueAnexo === cueAnexo
}

async function insertarEvento(params: {
  verificacionId: string
  tipo: 'respondida' | 'discrepancia_detectada'
  origen: OrigenRespuesta
  canal: CanalRespuesta
  ahoraIso: string
}): Promise<void> {
  const db = getDb()
  await db.insert(infraVerificacionEvento).values({
    id: randomUUID(),
    verificacionId: params.verificacionId,
    tipo: params.tipo,
    actorTipo: params.origen.tipo === 'enlace' ? 'enlace' : 'usuario',
    actorUserId: params.origen.tipo === 'asistida' ? params.origen.actorUserId : null,
    canal: params.canal,
    motivo: null,
    correlacionId: null,
    creadaEn: params.ahoraIso,
  })
}

// Núcleo compartido por las dos vías de respuesta (enlace público y carga
// asistida por staff). Parametrizado por origen para que la validación de la
// credencial y la atribución de la auditoría vivan en un solo lugar.
//
// Orden deliberado de los chequeos:
//   1. credencial (sólo enlace) ANTES del estado: una credencial inválida
//      nunca debe revelar si la solicitud existe, está cancelada o ya se
//      respondió. Mismo criterio para 403 y para los 410.
//   2. estado persistido, para resolver cancelación y replay idempotente.
//   3. escritura atómica condicionada, con un único reintento si perdió una
//      carrera contra una transición concurrente.
async function transicionarARespondida(
  verificacionId: string,
  resultado: ResultadoRespuesta,
  origen: OrigenRespuesta,
  movimientoId: string | null,
  ahora: Date,
): Promise<ResultadoTransicion> {
  const db = getDb()
  const ahoraIso = ahora.toISOString()
  const canal: CanalRespuesta = origen.tipo === 'enlace' ? 'enlace' : origen.canal

  // Máximo un reintento: si tras re-leer el estado volvemos a perder el
  // UPDATE condicionado, hay una tormenta de transiciones concurrentes que no
  // vale la pena seguir persiguiendo. El diseño congela "una vez más".
  for (let intento = 0; intento < 2; intento += 1) {
    const [fila] = await db
      .select()
      .from(infraVerificacion)
      .where(eq(infraVerificacion.id, verificacionId))
    if (!fila) return { ok: false, status: 404, motivo: 'no_existe' }

    if (origen.tipo === 'enlace') {
      if (hashearToken(origen.token) !== fila.tokenHash) {
        return { ok: false, status: 403, motivo: 'credencial_invalida' }
      }
      if (fila.tokenRevocadoEn !== null) {
        return { ok: false, status: 410, motivo: 'credencial_revocada' }
      }
      if (tokenExpirado(fila.tokenExpiraEn, ahora)) {
        return { ok: false, status: 410, motivo: 'credencial_vencida' }
      }
    }

    if (fila.estado === 'cancelada') {
      return { ok: false, status: 409, motivo: 'solicitud_cancelada' }
    }

    if (fila.estado === 'respondida') {
      // Retry idéntico: idempotente, no escribe un segundo evento. Un retry
      // con otra respuesta es un conflicto real del usuario, no un reintento.
      if (fila.resultado === resultado) return { ok: true, verificacion: fila, replay: true }
      return { ok: false, status: 409, motivo: 'respuesta_contradictoria' }
    }

    // fila.estado === 'pendiente': calcular discrepancia y escribir. La
    // consulta de afectación vigente usa el período del episodio, que es el
    // que ancla el parte del establecimiento.
    const episodio = await obtenerEpisodio(fila.episodioId)
    const hayAfectacion = episodio
      ? await existeAfectacionVigente(fila.cueAnexo, episodio.periodoId)
      : false
    const discrepancia = resultado === 'sin_afectacion' && hayAfectacion ? 1 : 0

    if (resultado === 'con_afectacion' && movimientoId !== null) {
      if (!(await movimientoPerteneceAlCue(movimientoId, fila.cueAnexo))) {
        return { ok: false, status: 409, motivo: 'movimiento_cue_no_coincide' }
      }
    }

    const [actualizada] = await db
      .update(infraVerificacion)
      .set({
        estado: 'respondida',
        resultado,
        respondidaEn: ahoraIso,
        respondidaCanal: canal,
        respondidaPorUserId: origen.tipo === 'asistida' ? origen.actorUserId : null,
        movimientoId,
        discrepancia,
        // La credencial se consume sólo cuando la respuesta vino por enlace.
        // La vía asistida no toca tokenConsumidoEn: el enlace sigue válido si
        // el director todavía no lo usó.
        tokenConsumidoEn: origen.tipo === 'enlace' ? ahoraIso : fila.tokenConsumidoEn,
        actualizadaEn: ahoraIso,
      })
      .where(
        and(
          eq(infraVerificacion.id, verificacionId),
          eq(infraVerificacion.estado, 'pendiente'),
        ),
      )
      .returning()

    if (!actualizada) continue // perdió la carrera: re-lee y reintenta una vez

    await insertarEvento({
      verificacionId,
      tipo: 'respondida',
      origen,
      canal,
      ahoraIso,
    })
    if (discrepancia === 1) {
      await insertarEvento({
        verificacionId,
        tipo: 'discrepancia_detectada',
        origen,
        canal,
        ahoraIso,
      })
    }
    return { ok: true, verificacion: actualizada }
  }

  // Se perdió la carrera dos veces seguidas: el estado siguió cambiando bajo
  // los pies. No es un camino alcanzable en operación normal; se informa como
  // conflicto en vez de inventar un resultado.
  return { ok: false, status: 409, motivo: 'conflicto_concurrente' }
}

export async function responderPorEnlace(
  input: ResponderPorEnlaceInput,
  ahora: Date = new Date(),
): Promise<ResultadoTransicion> {
  // Error de programación del caller, no un caso de usuario: una respuesta
  // 'con_afectacion' sin movimiento es un dato incompleto que no debe
  // persistirse.
  if (input.resultado === 'con_afectacion' && !input.movimientoId) {
    throw new Error('con_afectacion requiere movimientoId')
  }
  return transicionarARespondida(
    input.verificacionId,
    input.resultado,
    { tipo: 'enlace', token: input.token },
    input.movimientoId ?? null,
    ahora,
  )
}

export async function responderAsistida(
  input: ResponderAsistidaInput,
  ahora: Date = new Date(),
): Promise<ResultadoTransicion> {
  if (input.resultado === 'con_afectacion' && !input.movimientoId) {
    throw new Error('con_afectacion requiere movimientoId')
  }
  return transicionarARespondida(
    input.verificacionId,
    input.resultado,
    { tipo: 'asistida', actorUserId: input.actorUserId, canal: input.canal },
    input.movimientoId ?? null,
    ahora,
  )
}

// Chequeo de SÓLO LECTURA para que la página pública muestre el estado antes
// de que el director elija una respuesta. No escribe, no consume el token y no
// valida contra un resultado (todavía no hay uno). Misma secuencia de
// validación de credencial que transicionarARespondida, sin el paso de
// escritura. Si ya está respondida se devuelve igual como ok: la página
// necesita poder mostrar el resultado final, no ocultarlo.
export async function validarCredencial(
  input: { verificacionId: string; token: string },
  ahora: Date = new Date(),
): Promise<
  | { ok: true; verificacion: VerificacionRow }
  | { ok: false; status: 403 | 404 | 409 | 410; motivo: string }
> {
  const db = getDb()
  const [fila] = await db
    .select()
    .from(infraVerificacion)
    .where(eq(infraVerificacion.id, input.verificacionId))
  if (!fila) return { ok: false, status: 404, motivo: 'no_existe' }

  if (hashearToken(input.token) !== fila.tokenHash) {
    return { ok: false, status: 403, motivo: 'credencial_invalida' }
  }
  if (fila.tokenRevocadoEn !== null) {
    return { ok: false, status: 410, motivo: 'credencial_revocada' }
  }
  if (tokenExpirado(fila.tokenExpiraEn, ahora)) {
    return { ok: false, status: 410, motivo: 'credencial_vencida' }
  }
  if (fila.estado === 'cancelada') {
    return { ok: false, status: 409, motivo: 'solicitud_cancelada' }
  }
  return { ok: true, verificacion: fila }
}

// Regla de N1 (gate del batch E1): la sesión derivada del token nunca puede
// ser más fuerte que el token. Esta función es el único lugar que decide si
// una verificación sigue habilitando ESCRITURA: se usa tanto al canjear una
// sesión nueva (canjear-sesion) como en CADA request que reusa una sesión ya
// emitida (tieneAccesoAlParteParaCue en acceso-parte.ts) — nunca basta con
// que la cookie tenga firma/expiración válidas, la fila real de la
// verificación manda siempre.
export async function verificacionHabilitaSesionEscritura(
  verificacionId: string,
  ahora: Date = new Date(),
): Promise<boolean> {
  const fila = await obtenerVerificacion(verificacionId)
  if (!fila) return false
  if (fila.estado !== 'pendiente') return false
  if (fila.tokenConsumidoEn !== null) return false
  if (fila.tokenRevocadoEn !== null) return false
  if (tokenExpirado(fila.tokenExpiraEn, ahora)) return false
  return true
}

export async function obtenerVerificacion(
  verificacionId: string,
): Promise<VerificacionRow | null> {
  const db = getDb()
  const [fila] = await db
    .select()
    .from(infraVerificacion)
    .where(eq(infraVerificacion.id, verificacionId))
  return fila ?? null
}

export async function listarVerificaciones(
  input?: { episodioId?: string; cueAnexo?: string; estado?: 'pendiente' | 'respondida' | 'cancelada' },
): Promise<VerificacionRow[]> {
  const db = getDb()
  const condiciones = []
  if (input?.episodioId) condiciones.push(eq(infraVerificacion.episodioId, input.episodioId))
  if (input?.cueAnexo) condiciones.push(eq(infraVerificacion.cueAnexo, input.cueAnexo))
  if (input?.estado) condiciones.push(eq(infraVerificacion.estado, input.estado))

  const base = db.select().from(infraVerificacion)
  const conFiltro = condiciones.length > 0 ? base.where(and(...condiciones)) : base
  return conFiltro.orderBy(desc(infraVerificacion.solicitadaEn))
}

// Auditoría de un intento de vínculo fallido (batch E1): quien llama a esto ya
// tiene un movimiento real guardado (el parte del director se guardó bien) y
// el vínculo con la verificación de origen no prendió por el motivo que sea
// (credencial inválida/vencida/revocada, respuesta contradictoria, etc.). Esto
// NO reintenta la transición ni toca `estado`/`resultado`/`movimientoId` de la
// verificación: sólo dejar un rastro append-only para que el operador vea que
// hubo un intento de responder con afectación que no quedó enlazado. Si el id
// de verificación ni siquiera existe (token completamente ajeno/inventado), no
// hay nada real que auditar: no se escribe nada y se devuelve false.
export async function registrarIntentoVinculoFallido(
  input: { verificacionId: string; motivo: string },
  ahora: Date = new Date(),
): Promise<boolean> {
  const db = getDb()
  const [fila] = await db
    .select({ id: infraVerificacion.id })
    .from(infraVerificacion)
    .where(eq(infraVerificacion.id, input.verificacionId))
  if (!fila) return false

  await db.insert(infraVerificacionEvento).values({
    id: randomUUID(),
    verificacionId: input.verificacionId,
    tipo: 'vinculo_fallido',
    actorTipo: 'sistema',
    actorUserId: null,
    canal: null,
    motivo: input.motivo,
    correlacionId: null,
    creadaEn: ahora.toISOString(),
  })
  return true
}

import { createClient, type Client } from '@libsql/client'
import path from 'node:path'
import { getDataDir } from '../data-dir'
import type { GeCorte } from './types'

// Subconjunto de Client que también satisface una Transaction de libsql:
// permite que attachGe y las consultas de impacto.ts / identidad.ts corran
// tanto sobre una conexión suelta como dentro de una transacción explícita
// (ver app/api/mapas/infraestructura/nominal/route.ts, que loguea el acceso
// en la misma transacción que sirve la respuesta).
export type EjecutorSql = Pick<Client, 'execute'>

export function getGeSqlitePath(): string {
  return path.join(getDataDir(), 'ge.sqlite')
}

const GE_DDL: string[] = [
  `CREATE TABLE IF NOT EXISTS ge_corte (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ciclo_lectivo INTEGER NOT NULL,
    fetched_at TEXT NOT NULL,
    estado TEXT NOT NULL CHECK (estado IN ('importando','vigente','historico'))
  )`,
  `CREATE TABLE IF NOT EXISTS ge_seccion (
    corte_id INTEGER NOT NULL,
    ge_section_id INTEGER NOT NULL,
    cue_anexo TEXT NOT NULL,
    curso TEXT NOT NULL,
    division TEXT NOT NULL,
    nivel TEXT NOT NULL,
    turno TEXT NOT NULL,
    PRIMARY KEY (corte_id, ge_section_id)
  )`,
  `CREATE TABLE IF NOT EXISTS ge_alumno_seccion (
    corte_id INTEGER NOT NULL,
    ge_section_id INTEGER NOT NULL,
    ge_person_id INTEGER NOT NULL,
    PRIMARY KEY (corte_id, ge_section_id, ge_person_id)
  )`,
  `CREATE TABLE IF NOT EXISTS ge_localizacion (
    cue_anexo TEXT PRIMARY KEY,
    cui TEXT,
    nombre TEXT NOT NULL,
    departamento TEXT NOT NULL,
    localidad TEXT NOT NULL,
    lat REAL,
    lon REAL,
    geo_calidad TEXT
  )`,
  `CREATE TABLE IF NOT EXISTS ge_alumno_identidad (
    ge_person_id INTEGER PRIMARY KEY,
    payload_cifrado TEXT NOT NULL
  )`,
  `CREATE INDEX IF NOT EXISTS idx_ge_seccion_corte_cue ON ge_seccion (corte_id, cue_anexo)`,
  `CREATE INDEX IF NOT EXISTS idx_ge_alumno_seccion_corte_section ON ge_alumno_seccion (corte_id, ge_section_id)`,
]

export function openGeDb(): Client {
  return createClient({ url: `file:${getGeSqlitePath()}` })
}

export async function ensureGeSchema(client: Client): Promise<void> {
  for (const stmt of GE_DDL) {
    await client.execute(stmt)
  }
}

// Monta ge.sqlite como base adjunta 'ge' de solo-lectura sobre una conexión existente (p.ej. la del Hub).
// NUNCA hardcodees la ruta: siempre getGeSqlitePath(). Escapá comillas simples en la ruta duplicándolas.
export async function attachGe(hostClient: EjecutorSql): Promise<void> {
  const gePath = getGeSqlitePath().replace(/'/g, "''")
  await hostClient.execute(`ATTACH DATABASE 'file:${gePath}?mode=ro' AS ge`)
}

export async function getCorteVigente(client: Client): Promise<GeCorte | null> {
  const res = await client.execute(
    "SELECT id, ciclo_lectivo as cicloLectivo, fetched_at as fetchedAt, estado FROM ge_corte WHERE estado = 'vigente' ORDER BY id DESC LIMIT 1",
  )
  if (res.rows.length === 0) return null
  const row = res.rows[0] as unknown as GeCorte
  return row
}

export async function activarCorte(client: Client, corteId: number): Promise<void> {
  const corte = await client.execute('SELECT id, estado FROM ge_corte WHERE id = ?', [corteId])
  if (corte.rows.length === 0) {
    throw new Error(`Corte ${corteId} no existe`)
  }
  const estado = corte.rows[0].estado as string
  if (estado !== 'importando') {
    throw new Error(`Corte ${corteId} no está en estado 'importando'`)
  }

  const seccionesSinLocalizacion = await client.execute(
    `SELECT COUNT(*) AS n FROM ge_seccion s
     WHERE s.corte_id = ? AND NOT EXISTS (
       SELECT 1 FROM ge_localizacion l WHERE l.cue_anexo = s.cue_anexo
     )`,
    [corteId],
  )
  const seccionesFallan = Number(seccionesSinLocalizacion.rows[0].n)
  if (seccionesFallan > 0) {
    throw new Error(`${seccionesFallan} secciones referencian cue_anexo inexistente en ge_localizacion`)
  }

  const membresiasHuerfanas = await client.execute(
    `SELECT COUNT(*) AS n FROM ge_alumno_seccion m
     WHERE m.corte_id = ? AND NOT EXISTS (
       SELECT 1 FROM ge_seccion s WHERE s.corte_id = m.corte_id AND s.ge_section_id = m.ge_section_id
     )`,
    [corteId],
  )
  const membresiasFallan = Number(membresiasHuerfanas.rows[0].n)
  if (membresiasFallan > 0) {
    throw new Error(`${membresiasFallan} membresías apuntan a ge_seccion inexistente`)
  }

  const tx = await client.transaction('write')
  try {
    await tx.execute({
      sql: "UPDATE ge_corte SET estado = 'historico' WHERE estado = 'vigente' AND id != ?",
      args: [corteId],
    })
    await tx.execute({ sql: "UPDATE ge_corte SET estado = 'vigente' WHERE id = ?", args: [corteId] })
    await tx.commit()
  } catch (err) {
    try {
      await tx.rollback()
    } catch {
      // noop: si el commit ya cerró la transacción, el error original manda
    }
    throw err
  }
}

